using System.Collections.Generic;
using FPS.Core;
using UnityEngine;

namespace FPS.World
{
    /// <summary>
    /// Ordered list of waypoints (the child transforms) used by bots when they have no objective or threat.
    /// Generated by the map builder for every tactical zone; designers can add or move routes freely.
    /// </summary>
    public class PatrolRoute : MonoBehaviour
    {
        [SerializeField] private Team m_TeamAffinity = Team.Neutral;
        [SerializeField] private bool m_Loop = true;
        [SerializeField] private Color m_GizmoColor = new Color(0.4f, 1f, 0.4f, 0.8f);

        private static readonly List<PatrolRoute> s_Routes = new List<PatrolRoute>(32);
        private readonly List<Transform> m_Waypoints = new List<Transform>(16);

        public static IReadOnlyList<PatrolRoute> All => s_Routes;
        public Team TeamAffinity => m_TeamAffinity;
        public bool Loop => m_Loop;
        public int Count => m_Waypoints.Count;

        public void Configure(Team affinity, bool loop)
        {
            m_TeamAffinity = affinity;
            m_Loop = loop;
        }

        private void OnEnable()
        {
            CacheWaypoints();
            if (!s_Routes.Contains(this))
            {
                s_Routes.Add(this);
            }
        }

        private void OnDisable()
        {
            s_Routes.Remove(this);
        }

        private void CacheWaypoints()
        {
            m_Waypoints.Clear();
            foreach (Transform child in transform)
            {
                m_Waypoints.Add(child);
            }
        }

        public Vector3 GetWaypoint(int index)
        {
            if (m_Waypoints.Count == 0)
            {
                return transform.position;
            }

            return m_Waypoints[Mathf.Abs(index) % m_Waypoints.Count].position;
        }

        public int ClosestIndex(Vector3 position)
        {
            int best = 0;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < m_Waypoints.Count; i++)
            {
                float distance = (m_Waypoints[i].position - position).sqrMagnitude;
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    best = i;
                }
            }

            return best;
        }

        public static PatrolRoute FindClosest(Vector3 position, Team team)
        {
            PatrolRoute best = null;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < s_Routes.Count; i++)
            {
                PatrolRoute route = s_Routes[i];
                if (route.Count == 0 || (route.m_TeamAffinity != Team.Neutral && route.m_TeamAffinity != team))
                {
                    continue;
                }

                float distance = (route.GetWaypoint(route.ClosestIndex(position)) - position).sqrMagnitude;
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    best = route;
                }
            }

            return best;
        }

        private void OnDrawGizmos()
        {
            Gizmos.color = m_GizmoColor;
            int count = transform.childCount;
            for (int i = 0; i < count; i++)
            {
                Vector3 a = transform.GetChild(i).position;
                Gizmos.DrawSphere(a + Vector3.up * 0.2f, 0.25f);
                if (i + 1 < count || m_Loop)
                {
                    Vector3 b = transform.GetChild((i + 1) % count).position;
                    Gizmos.DrawLine(a + Vector3.up * 0.2f, b + Vector3.up * 0.2f);
                }
            }
        }
    }
}
